local config = {
  ui_story_30930401_1_dialog_content = "What took you so long, Navigator? I got so bored I fell asleep...",
  ui_story_30930401_2_dialog_content = "I was moving as fast as I could...",
  ui_story_30930401_3_dialog_content = "So what do you want to talk about?",
  ui_story_30930401_4_dialog_content = "Uh... How should I put this...",
  ui_story_30930401_5_dialog_content = "I've been getting a lot of... <color=#FFB400>complaints</color>... about you recently.",
  ui_story_30930401_6_dialog_content = "They've been <color=#FFB400>reporting</color> me, I know. Just tell me like it is, instead of beating around the bush and reporting to those Federation officials.",
  ui_story_30930401_7_dialog_content = "Oh, well since you're aware of it, this shouldn't be an issue...",
  ui_story_30930401_8_dialog_content = "No, wait Migard! If we don't take this seriously, nothing's going to change!",
  ui_story_30930401_9_dialog_content = "Now then, I wanted to talk to you privately so you could help me understand... How that sort of thing happened.",
  ui_story_30930401_10_dialog_content = "...",
  ui_story_30930401_11_dialog_content = "Interesting. You seem to be yet another one of those people who take a deep interest in others.",
  ui_story_30930401_12_dialog_content = "Huh? \"Yet another\"?",
  ui_story_30930401_13_dialog_content = "To be honest, I know exactly what they're thinking, the people who are complaining about me.",
  ui_story_30930401_14_dialog_content = "\"Migard is always giving me this weird look,\" \"Migard always says such strange things,\"",
  ui_story_30930401_15_dialog_content = "\"Migard stands way too close,\" \"Migard likes to secretly collect people's hair...\"",
  ui_story_30930401_16_dialog_content = "Y-You what?! I haven't heard that last one before! What kind of hobby is that?!",
  ui_story_30930401_17_dialog_content = "<color=#FFB400>Gronru</color>, <color=#FFB400>Lilliam</color>, and <color=#FFB400>Nemesis</color> are the ones who mentioned those things to you, right?",
  ui_story_30930401_18_dialog_content = "Wow, right on point... Wait, I shouldn't give away their identities...",
  ui_story_30930401_19_dialog_content = "It's fine, I already knew. Besides, they're my most preferred test subjects.",
  ui_story_30930401_20_dialog_content = "In other words, they're the main targets of my \"harassment.\"",
  ui_story_30930401_21_dialog_content = "She even acknowledges that what she's doing is harassment...",
  ui_story_30930401_22_dialog_content = "You all call it \"harassment\", but I call it \"understanding.\"",
  ui_story_30930401_23_dialog_content = "In any case, it seems you and the others have a large disagreement. As the Navigator, it's my responsibility to think of a solution...",
  ui_story_30930401_24_dialog_content = "Migard, could you tell me more about your, uh... interactions?",
  ui_story_30930401_25_dialog_content = "I can't do that.",
  ui_story_30930401_26_dialog_content = "What?!",
  ui_story_30930401_27_dialog_content = "Your method of questioning is so incredibly dull, it's boring me to death.",
  ui_story_30930401_28_dialog_content = "Then what kind of method would you prefer?",
  ui_story_30930401_29_dialog_content = "How about <color=#FFB400>role-playing</color>?",
  ui_story_30930401_30_dialog_content = "What do you mean?",
  ui_story_30930401_31_dialog_content = "You pretend to be Gronru, Lilliam, and Nemesis, and I'll be myself.",
  ui_story_30930401_32_dialog_content = "I'll simulate our usual conversations, so you can better understand our previous <color=#FFB400>interactions</color>.",
  ui_story_30930401_33_dialog_content = "...",
  ui_story_30930401_34_dialog_content = "Heheheheh....",
  ui_story_30930401_35_dialog_content = "*Sweats profusely*",
  ui_story_30930401_36_dialog_content = "If you don't experience it for yourself at least once, anything I tell you can be regarded as hearsay.",
  ui_story_30930401_37_dialog_content = "(I don't like where this is going...)",
  ui_story_30930401_38_dialog_content = "Okay, then... I'll do my best to play their part.",
  ui_story_30930401_39_dialog_content = "Who should I start with?",
  ui_story_30930401_40_option_content = "Gronru",
  ui_story_30930401_41_dialog_content = "...",
  ui_story_30930401_42_dialog_content = "Tap, tap, tap.",
  ui_story_30930401_43_dialog_content = "What are you doing?",
  ui_story_30930401_44_dialog_content = "Hmm? I... I'm playing video games!",
  ui_story_30930401_45_dialog_content = "Tap, tap, tap, pop!",
  ui_story_30930401_46_dialog_content = "Flawless clear! A new record for the Illumina Federation! Although I was the one who set the last record...",
  ui_story_30930401_47_dialog_content = "You're exaggerating a bit, Navigator.",
  ui_story_30930401_48_dialog_content = "Don't make me break character! I'm doing my best Gronru impersonation, okay?!",
  ui_story_30930401_49_dialog_content = "How diligent. You know, diligent people get my attention in a very special way...",
  ui_story_30930401_50_dialog_content = "(Looks like Migard's getting into character, too...)",
  ui_story_30930401_51_dialog_content = "Gronru, how is that experiment report from before coming along?",
  ui_story_30930401_52_dialog_content = "Huh? I... Uh, line, please...",
  ui_story_30930401_53_dialog_content = "\"The clinical research on interneural communications among various species of organisms.\"",
  ui_story_30930401_54_dialog_content = "Ah! You mean the report on \"inter-something complications among various something-or-others\"!",
  ui_story_30930401_55_dialog_content = "I have it right here!",
  ui_story_30930401_56_dialog_content = "Okay.",
  ui_story_30930401_57_dialog_content = "W-What are you doing, Migard?",
  ui_story_30930401_58_dialog_content = "Such a nice scent.",
  ui_story_30930401_59_dialog_content = "Did you switch to a new shower gel, Gronru?",
  ui_story_30930401_60_dialog_content = "(Is she flirting?)",
  ui_story_30930401_61_dialog_content = "I used that scent before, too.",
  ui_story_30930401_62_dialog_content = "It feels like we're getting closer...",
  ui_story_30930401_63_dialog_content = "Oh, my bathroom is pretty big. Want to see it?",
  ui_story_30930401_64_dialog_content = "Crap, this can't be good! No wonder she reported her!!",
  ui_story_30930401_65_dialog_content = "You could get thrown in jail for this sort of thing!!",
  ui_story_30930401_66_dialog_content = "Why? I'm just expressing appreciation for our common interest.",
  ui_story_30930401_67_dialog_content = "No Migard, what you're doing is getting ready to commit a crime.",
  ui_story_30930401_68_dialog_content = "Ah, how dull. Here I thought you would be a little more fun, Navigator.",
  ui_story_30930401_69_dialog_content = "There's nothing \"fun\" about any of this... You need to control your desires, Migard...",
  ui_story_30930401_70_dialog_content = "But my desires are what have made me and Black Umbrella Laboratories what we are today.",
  ui_story_30930401_71_dialog_content = "A scientist without desires is no scientist at all, Navigator. It's as simple as that.",
  ui_story_30930401_72_dialog_content = "That's not the same thing!",
  ui_story_30930401_73_dialog_content = "Heheh, you're so cute when you get flustered like this...",
  ui_story_30930401_74_dialog_content = "Now then, your next role will be...",
  ui_story_30930401_75_option_content = "Lilliam",
  ui_story_30930401_76_dialog_content = "Shwoop, shwoop.",
  ui_story_30930401_77_dialog_content = "Shwoop, shwoop, shwoop.",
  ui_story_30930401_78_dialog_content = "And just what is that weird noise supposed to be?",
  ui_story_30930401_79_dialog_content = "The sound of Lilliam sweeping the floor...",
  ui_story_30930401_80_dialog_content = "Since this is Lilliam we're talking about, shouldn't she be quietly performing her maid duties?",
  ui_story_30930401_81_dialog_content = "It all depends on which Lilliam we're talking about, but... Heheh, I like them all the same.",
  ui_story_30930401_82_dialog_content = "Warning. Translating: Lewd intentions detected. Exercise caution.",
  ui_story_30930401_83_dialog_content = "Oh, are we starting already? Then I should get serious, as well...",
  ui_story_30930401_84_dialog_content = "Oh, Lilliam? Would you like to try this new probiotic drink from the Black Umbrella Laboratories?",
  ui_story_30930401_85_dialog_content = "Question. Translating: Define \"probiotic beverage\" please.",
  ui_story_30930401_86_dialog_content = "It's just fruit juice! It's really fresh, and it is said that this kind of fruit...",
  ui_story_30930401_87_dialog_content = "Is an aphrodisiac.",
  ui_story_30930401_88_dialog_content = "Question, no, I mean, access denied! Please avoid making such openly disturbing statements!!",
  ui_story_30930401_89_dialog_content = "But why? I just want to understand you better, Lilliam... All of you.",
  ui_story_30930401_90_dialog_content = "Everyone says Lilliam No. 1 is just a soulless, robotic maid... But I don't think so.",
  ui_story_30930401_91_dialog_content = "On the contrary, I think every living thing is capable of feeling a wide spectrum of emotions, good or bad.",
  ui_story_30930401_92_dialog_content = "Even my Diving Spines gets a little cranky if I don't sterilize them properly.",
  ui_story_30930401_93_dialog_content = "Shocked expression: Can those things really behave like spoiled household pets?",
  ui_story_30930401_94_dialog_content = "I'm only kidding. In any case, what I really want... is to trigger some emotion from you, Lilliam.",
  ui_story_30930401_95_dialog_content = "You're not a robot, but a person just like me, Lilliam. And just like me, you must have feelings and desires, too...",
  ui_story_30930401_96_dialog_content = "Danger detected! Snap out of it, Migard! I'm not really Lilliam!!!",
  ui_story_30930401_97_dialog_content = "A-Ah, sorry about that. I got lost in my character... It's all your fault, Navigator. You are good at acting, you know?",
  ui_story_30930401_98_dialog_content = "Now then, your next role will be...",
  ui_story_30930401_99_option_content = "Nemesis",
  ui_story_30930401_100_dialog_content = "Hey!",
  ui_story_30930401_101_dialog_content = "Ha!!",
  ui_story_30930401_102_dialog_content = "Hello, Nemesis! Doing some calisthenics, are we?",
  ui_story_30930401_103_dialog_content = "This... is training! Training to preserve and execute justice!",
  ui_story_30930401_104_dialog_content = "Are my movements off? Off form?",
  ui_story_30930401_105_dialog_content = "No, it's very good. It's just... It looks like each of your limbs has a mind of its own.",
  ui_story_30930401_106_dialog_content = "Ahem! T-That's not important! Anyway... As long as you maintain a sense of justice in your heart, we will always be comrades-in-arms!",
  ui_story_30930401_107_dialog_content = "So does that mean you would punish someone if they stood against justice, Nemesis?",
  ui_story_30930401_108_dialog_content = "<size=50>Without a second thought!</size>",
  ui_story_30930401_109_dialog_content = "(Urgh... How does Nemesis talk like this all the time? My throat's about to give out...)",
  ui_story_30930401_110_dialog_content = "I see... Evildoers must be punished, eh...",
  ui_story_30930401_111_dialog_content = "...",
  ui_story_30930401_112_dialog_content = "Migard... When did you start acting so suspiciously?",
  ui_story_30930401_113_dialog_content = "Suspicious? Me? But I haven't said a word, dear.",
  ui_story_30930401_114_dialog_content = "It's just... When you girls get all worked up like this, your bodies give off this... irresistible magnetism.",
  ui_story_30930401_115_dialog_content = "What exactly do you want, Migard of Black Umbrella Laboratories? Justice has no time to waste.",
  ui_story_30930401_116_dialog_content = "I, uh... I want...",
  ui_story_30930401_117_dialog_content = "To turn myself in.",
  ui_story_30930401_118_dialog_content = "Even though I have been fully prepared for this, your words still catch me off-guard.",
  ui_story_30930401_119_dialog_content = "Speak. Which law of the Illumina Federation have you violated?",
  ui_story_30930401_120_dialog_content = "N-No, I haven't violated any law, but I'm about to...",
  ui_story_30930401_121_dialog_content = "Against a certain... defender of justice...",
  ui_story_30930401_122_dialog_content = "W-What?! What are you plotting?!",
  ui_story_30930401_123_dialog_content = "As the General Inspector, how do you maintain such a high level of vigilance at all hours of the day, Nemesis?",
  ui_story_30930401_124_dialog_content = "How is it that you can endure even the strongest temptations, just to stick to those stuffy, old rules? I really want to find out...",
  ui_story_30930401_125_dialog_content = "Might I interest you in a short trip to my lab?",
  ui_story_30930401_126_dialog_content = "Don't forget, Migard, I'm not really Nemesis...",
  ui_story_30930401_127_dialog_content = "Ah, I nearly forgot.",
  ui_story_30930401_128_dialog_content = "You really do have potential in acting, Navigator. Now you're starting to get my attention, as well...",
  ui_story_30930401_129_dialog_content = "Now then, your next role will be...",
  ui_story_30930401_130_option_content = "I think we're done here",
  ui_story_30930401_131_dialog_content = "Enough, enough! Let's just stop, already...",
  ui_story_30930401_132_dialog_content = "If we keep going, I'm scared you won't be able to stop yourself, Migard...",
  ui_story_30930401_133_dialog_content = "...",
  ui_story_30930401_134_dialog_content = "...",
  ui_story_30930401_135_dialog_content = "Heheh.",
  ui_story_30930401_136_dialog_content = "It's too late! Migard sees me as a <color=#FFB400>test subject</color> now!!",
  ui_story_30930401_137_dialog_content = "Oh, absolutely. I don't think I'll be as bored as I used to be from now on...",
  ui_story_30930401_138_dialog_content = "W-Wait, Migard! I know what the problem is now!",
  ui_story_30930401_139_dialog_content = "Hmm? What problem?",
  ui_story_30930401_140_dialog_content = "The problem that everyone's been reporting you for! The problem...",
  ui_story_30930401_141_option_content = "Is the way you \"research\" everyone!",
  ui_story_30930401_142_dialog_content = "Not everyone is like you, Migard! Not everyone has a burning passion for research that borders on perversion...",
  ui_story_30930401_143_dialog_content = "You don't hide your emotions, and that's wonderful! Honesty is a good thing!",
  ui_story_30930401_144_dialog_content = "But on the other hand, harassment is wrong no matter how you look at it.",
  ui_story_30930401_145_dialog_content = "...",
  ui_story_30930401_146_dialog_content = "So next time, why not change your approach? Be less aggressive, and don't do anything like this without the other person's consent.",
  ui_story_30930401_147_dialog_content = "Or maybe do your research in writing! That way, even people who don't want to participate in person can...",
  ui_story_30930401_148_option_content = "Is your choice of test subjects!",
  ui_story_30930401_149_dialog_content = "Not everyone is willing to put up with your special brand of \"research\", Migard!",
  ui_story_30930401_150_dialog_content = "So why not, uh... start with people you're closer to? Try working with them first...",
  ui_story_30930401_151_dialog_content = "Then slowly expand your subject base as time goes on. That's a pretty reasonable method of scientific advancement, right?",
  ui_story_30930401_152_dialog_content = "...",
  ui_story_30930401_153_dialog_content = "Are you listening, Migard?!",
  ui_story_30930401_154_dialog_content = "I'm really trying to help here! Not just you, but everybody as well...",
  ui_story_30930401_155_dialog_content = "Heheh... Heheheheh....",
  ui_story_30930401_156_dialog_content = "Could you not laugh like that?! My survival instincts are already screaming at me to get the heck out of here...",
  ui_story_30930401_157_dialog_content = "Interesting.",
  ui_story_30930401_158_dialog_content = "You really are interesting, Navigator.",
  ui_story_30930401_159_dialog_content = "I've made my decision.",
  ui_story_30930401_160_dialog_content = "What decision...",
  ui_story_30930401_161_dialog_content = "You will be my newest test subject...",
  ui_story_30930401_162_dialog_content = "What? No! Wait, I mean...",
  ui_story_30930401_163_dialog_content = "You're going to show me EXACTLY how to research other people, step by step...",
  ui_story_30930401_164_dialog_content = "Wait, Migard!",
  ui_story_30930401_165_dialog_content = "There's no going back on your word now, Navigator...",
  ui_story_30930401_166_dialog_content = "Migard, nooooo!!!",
  ui_story_30930601_1_dialog_content = "(I've been playing a lot of games with Gronru lately.)",
  ui_story_30930601_2_dialog_content = "(As a result, not only did I start picking up her habits, I also started helping her out with her work.)",
  ui_story_30930601_3_dialog_content = "Can you think of a scarier game than this?",
  ui_story_30930601_4_dialog_content = "This kind of game must have an 18+ tag on the cover...",
  ui_story_30930601_5_dialog_content = "The text content within has lots of foul language and suggestive words.",
  ui_story_30930601_6_dialog_content = "It'd have a big label reading \"Parental Advisory: Explicit Content\" on it.",
  ui_story_30930601_7_dialog_content = "Even the greatest gamers in Illumina wouldn't want to play a game like this...",
  ui_story_30930601_8_dialog_content = "Usually, I would say that we're just here to deliver some materials and nothing more.",
  ui_story_30930601_9_dialog_content = "But when I realized the delivery was for <color=#FFB400>Migard</color>, and the delivery location was for <color=#FFB400>her lounge</color>...",
  ui_story_30930601_10_dialog_content = "I have to say you're right this time, Gronru.",
  ui_story_30930601_11_dialog_content = "You think so, too?",
  ui_story_30930601_12_dialog_content = "Yeah... After all, I've been on the receiving end of her torture.",
  ui_story_30930601_13_dialog_content = "And let me tell you, that smile of hers... It's not something you can easily forget.",
  ui_story_30930601_14_dialog_content = "And that's why I came up with a strategy!",
  ui_story_30930601_15_dialog_content = "I get it! You want to team up, right?",
  ui_story_30930601_16_dialog_content = "Yeah, that might work... With the two of us, we might stand a chance against a powerful boss like her!",
  ui_story_30930601_17_dialog_content = "You're right! But that's only step one of the plan.",
  ui_story_30930601_18_dialog_content = "The next step...",
  ui_story_30930601_19_dialog_content = "Is for me to log off!",
  ui_story_30930601_20_dialog_content = "<size=50>It's all up to you now, PlayerName!!</size>",
  ui_story_30930601_21_dialog_content = "<size=45>Up to you now!</size>",
  ui_story_30930601_22_dialog_content = "<size=40>You now!</size>",
  ui_story_30930601_23_dialog_content = "<size=35>Now!</size>",
  ui_story_30930601_24_dialog_content = "Eh?! Is this really part of your plan?!",
  ui_story_30930601_25_dialog_content = "You're gonna leave me to tackle a high-HP boss like Migard all by myself?!",
  ui_story_30930601_26_dialog_content = "...",
  ui_story_30930601_27_dialog_content = "(And here I thought Gronru and I were closer than that, after all the gaming we've done together...)",
  ui_story_30930601_28_dialog_content = "(I'll have to pick a better teammate next time.)",
  ui_story_30930601_29_dialog_content = "As long as I leave this on Migard's doorstep...",
  ui_story_30930601_30_dialog_content = "My job will be done, and I can get out of here.",
  ui_story_30930601_31_dialog_content = "I just have to do it nice and quietly...",
  ui_story_30930601_32_dialog_content = "Or you can give it to me directly.",
  ui_story_30930601_33_dialog_content = "Oh, well if you insist...",
  ui_story_30930601_34_dialog_content = "Huh?",
  ui_story_30930601_35_dialog_content = "(And before I knew it, the boss encounter had already begun.)",
  ui_story_30930601_36_dialog_content = "(Only this time, the boss' appearance wasn't like before. She appeared to be in her casual form.)",
  ui_story_30930601_37_dialog_content = "(Some elements have been emphasized to show her body shape... I guess it's trendy out there...)",
  ui_story_30930601_38_dialog_content = "(Even so, I can't underestimate her. She's already released her first skill... I'm petrified.)",
  ui_story_30930601_39_dialog_content = "(I can't move at all right now.)",
  ui_story_30930601_40_dialog_content = "Stunned, PlayerName? Heheh... Well, I suppose it can't be helped. You're still young, after all.",
  ui_story_30930601_41_dialog_content = "Uh... N-No, I'm just here to deliver the experiment materials, that's all. I'll be on my way now...",
  ui_story_30930601_42_dialog_content = "Don't be in such a hurry.",
  ui_story_30930601_43_dialog_content = "(There's her second skill... Suppression.)",
  ui_story_30930601_44_dialog_content = "(She's picking me up by the collar! My feet are completely off the ground!)",
  ui_story_30930601_45_dialog_content = "*Spluttering* Let... let me go...",
  ui_story_30930601_46_dialog_content = "You still have some room to grow taller, it seems.",
  ui_story_30930601_47_dialog_content = "Well, since you're here... Don't think you can leave so easily.",
  ui_story_30930601_48_dialog_content = "Won't you come in and keep me company for a while?",
  ui_story_30930601_49_dialog_content = "(And there's her third skill... Transform the battlefield.)",
  ui_story_30930601_50_dialog_content = "(Ah, I closed my eyes without even realizing it... But I'm too scared to open them.)",
  ui_story_30930601_51_dialog_content = "There's nothing to be afraid of here.",
  ui_story_30930601_52_dialog_content = "See?",
  ui_story_30930601_53_dialog_content = "...",
  ui_story_30930601_54_dialog_content = "Is... is this a laboratory?",
  ui_story_30930601_55_dialog_content = "But I thought we were at the doorway to your lounge?",
  ui_story_30930601_56_dialog_content = "Could it be that door... Was actually a portal?",
  ui_story_30930601_57_dialog_content = "One that lets her traverse time and space?",
  ui_story_30930601_58_dialog_content = "What's the matter? Don't you like my room?",
  ui_story_30930601_59_dialog_content = "I-It's very unique! Peaceful and mysterious!",
  ui_story_30930601_60_dialog_content = "Of course the boss room would have a detailed background like this...",
  ui_story_30930601_61_dialog_content = "It sounds like you've been spending a lot of time with Gronru lately.",
  ui_story_30930601_62_dialog_content = "You've even picked up on some of her speech patterns.",
  ui_story_30930601_63_dialog_content = "Hehehe... This kind of compatibility... Oh, hard to resist.",
  ui_story_30930601_64_dialog_content = "Y-You... I... Uh...",
  ui_story_30930601_65_dialog_content = "You even look like her when you're embarrassed...",
  ui_story_30930601_66_dialog_content = "This kind of tension and excitement can elicit a strong nervous response.",
  ui_story_30930601_67_dialog_content = "It makes your heartbeat quicken and your blood vessels expand, ultimately resulting in a blushing face.",
  ui_story_30930601_68_dialog_content = "And in certain instances, uncontrollable sweating.",
  ui_story_30930601_69_dialog_content = "*Slurp*",
  ui_story_30930601_70_dialog_content = "... You're being weird, do you know that?",
  ui_story_30930601_71_dialog_content = "Anyway, are these... biological specimens?",
  ui_story_30930601_72_dialog_content = "Books and materials all over the floor, and you're still wearing your lab coat.",
  ui_story_30930601_73_dialog_content = "Are you working right now? If I remember correctly, today is supposed to be your day off.",
  ui_story_30930601_74_dialog_content = "A person can take breaks from their work, but career requires a person's full time and attention.",
  ui_story_30930601_75_dialog_content = "Even when they're off the clock...",
  ui_story_30930601_76_dialog_content = "A comfortable environment can improve productivity in some cases.",
  ui_story_30930601_77_dialog_content = "Well, I wouldn't want to disturb your work...",
  ui_story_30930601_78_dialog_content = "I'm actually quite grateful for the interruption. As it were, I've hit something of a block in my research.",
  ui_story_30930601_79_dialog_content = "All of my previous experiments had failed, but luckily Gronru was able to find <color=#FFB400>this bottle of solvent</color> for me.",
  ui_story_30930601_80_dialog_content = "Oh... So what is it for?",
  ui_story_30930601_81_dialog_content = "It's used in separation and purification.",
  ui_story_30930601_82_dialog_content = "Simply put, I am trying to separate something from a crystal through heating and the use of this solvent.",
  ui_story_30930601_83_dialog_content = "Through the difference in solubility of various solid compounds in solutions...",
  ui_story_30930601_84_dialog_content = "Er... You look a little lost.",
  ui_story_30930601_85_dialog_content = "Let's say, for example, you and Barton step into a sauna at the same time.",
  ui_story_30930601_86_dialog_content = "With his thick skin, he can withstand the heat of the sauna for 30 minutes without melting.",
  ui_story_30930601_87_dialog_content = "You, on the other hand, would only last 3 minutes before turning into a puddle.",
  ui_story_30930601_88_dialog_content = "As such, I would be able to pull an entire Barton out of the sauna without you.",
  ui_story_30930601_89_dialog_content = "Are you saying you'd leave me to burn up in the sauna, then?!",
  ui_story_30930601_90_dialog_content = "However, this method has its limitations, especially when starting from scratch.",
  ui_story_30930601_91_dialog_content = "Choosing the right solvent is crucial, one that doesn't react with the purified object that I am trying to retrieve. This is where the difficulty lies.",
  ui_story_30930601_92_dialog_content = "For example, due to their incompatibility, an old and idyllic lifestyle would be a \"solvent\" that didn't react with Barton.",
  ui_story_30930601_93_dialog_content = "In my preliminary screenings, I eliminated quite a number of potential solvents.",
  ui_story_30930601_94_dialog_content = "Should I give you another comparison for how the screening process went?",
  ui_story_30930601_95_dialog_content = "It was like...",
  ui_story_30930601_96_dialog_content = "<color=#e8d9bb>And so, Migard spent about an hour giving PlayerName an abridged explanation of her work.</color>",
  ui_story_30930601_97_dialog_content = "(My head's full of Migard's weird comparisons... I feel like this has nothing to do with science.)",
  ui_story_30930601_98_dialog_content = "(Even so, seeing Migard's face so full of excitement... I can tell she's really passionate about this.)",
  ui_story_30930601_99_dialog_content = "Anyway, after everything is said and done, it's time to perform the experiment now, right?",
  ui_story_30930601_100_dialog_content = "Correct.",
  ui_story_30930601_101_dialog_content = "In that case, I won't bother you anymore...",
  ui_story_30930601_102_dialog_content = "After all, having someone like me around would only get in your way.",
  ui_story_30930601_103_dialog_content = "I'll be going now, but I'm sure your experiment will be a success, Migard!",
  ui_story_30930601_104_dialog_content = "You have a point.",
  ui_story_30930601_105_dialog_content = "I'll deliver the news to you later, PlayerName.",
  ui_story_30930601_106_dialog_content = "(But after that, several days passed before I saw Migard again.)",
  ui_story_30930601_107_dialog_content = "So, do you have any word on Migard or how she's doing?",
  ui_story_30930601_108_dialog_content = "Not really, no. All I know is that she hasn't left her lounge in days.",
  ui_story_30930601_109_dialog_content = "The boss seems to have lost her roaming mechanic, huh?",
  ui_story_30930601_110_dialog_content = "Speaking of which, I found a new game to play recently!",
  ui_story_30930601_111_dialog_content = "What do you say, PlayerName? Wanna play a few matches?",
  ui_story_30930601_112_dialog_content = "Not today, Gronru. I should go see how she's doing.",
  ui_story_30930601_113_dialog_content = "Not afraid to face her on your own anymore, eh, PlayerName? You really have leveled up!",
  ui_story_30930601_114_dialog_content = "(Uh...)",
  ui_story_30930601_115_dialog_content = "(It's still way too scary. Maybe I should just retreat for now...)",
  ui_story_30930601_116_dialog_content = "(Slowly... Quietly...)",
  ui_story_30930601_117_dialog_content = "<color=#e8d9bb>Boom!!!</color>",
  ui_story_30930601_118_dialog_content = "An explosion?!",
  ui_story_30930601_119_dialog_content = "Migard! Are you okay?!",
  ui_story_30930601_120_dialog_content = "Migard!",
  ui_story_30930601_121_dialog_content = "<color=#e8d9bb>Crumble...</color>",
  ui_story_30930601_122_dialog_content = "Oh... It's you, PlayerName.",
  ui_story_30930601_123_dialog_content = "That explosion just now...",
  ui_story_30930601_124_dialog_content = "It was a small side effect of the experiment, that's all.",
  ui_story_30930601_125_dialog_content = "As long as you're okay... We haven't seen you in days, Migard. I was starting to worry.",
  ui_story_30930601_126_dialog_content = "You plucked up the courage to come see me, even though you were so afraid?",
  ui_story_30930601_127_dialog_content = "You even charged into my lounge... Out of concern for my safety?",
  ui_story_30930601_128_dialog_content = "PlayerName... You're too lovely, I feel like I can't help myself...",
  ui_story_30930601_129_dialog_content = "But now that I look at the time, I suppose I am overdue for a bit of fresh air.",
  ui_story_30930601_130_dialog_content = "Have you finished your experiment?",
  ui_story_30930601_131_dialog_content = "Yes... despite how time-consuming it was, I finally achieved a satisfactory result.",
  ui_story_30930601_132_dialog_content = "You look a lot more relaxed... Did the experiment go well, then?",
  ui_story_30930601_133_dialog_content = "I suppose.",
  ui_story_30930601_134_dialog_content = "After all, it's you we're talking about. No experiment stands a chance against you and your Divine Spines, Migard.",
  ui_story_30930601_135_dialog_content = "You also spent all this time and effort on it, too.",
  ui_story_30930601_136_dialog_content = "No, PlayerName. The experiment was a complete and utter failure.",
  ui_story_30930601_137_dialog_content = "In the end, a large amount of impurities still existed within the crystal.",
  ui_story_30930601_138_dialog_content = "Huh?",
  ui_story_30930601_139_dialog_content = "There were simply too many variables and factors to take into account.",
  ui_story_30930601_140_dialog_content = "It's as though we suddenly discovered that Barton could withstand sitting in a sauna at 100°C.",
  ui_story_30930601_141_dialog_content = "Perhaps it was due to his indomitable willpower.",
  ui_story_30930601_142_dialog_content = "Or perhaps he had simply made a bet with Wrath, and decided he could not afford to lose.",
  ui_story_30930601_143_dialog_content = "Or perhaps he had already modified his entire body into a steel-crafted weapon of warfare.",
  ui_story_30930601_144_dialog_content = "Maybe, we can skip the part about Barton and saunas...",
  ui_story_30930601_145_dialog_content = "So then...",
  ui_story_30930601_146_dialog_content = "Don't look so nervous. I'm perfectly fine, or rather, my spirits are quite high.",
  ui_story_30930601_147_dialog_content = "You're in a good mood even after your experiment failed?",
  ui_story_30930601_148_dialog_content = "You don't think achieving success in an experiment is that easy, do you, PlayerName?",
  ui_story_30930601_149_dialog_content = "It's hard to say, since all I've ever seen from you are successful projects.",
  ui_story_30930601_150_dialog_content = "You are correct. Those successful experiments outshone the failures, covered everything up.",
  ui_story_30930601_151_dialog_content = "Even the smallest of successes rest on a mountain of a thousand failures.",
  ui_story_30930601_152_dialog_content = "Success is not easy to achieve, especially when it comes to science. Indeed, it is usually accidental and always the minority when it comes to results.",
  ui_story_30930601_153_dialog_content = "Even the success of my Diving Spines was a matter of pure coincidence.",
  ui_story_30930601_154_dialog_content = "And in a lot of instances, researchers spend their entire lives in pursuit of a handful of successful outcomes.",
  ui_story_30930601_155_dialog_content = "But in the end, all the success was only pushing our cognitive barriers one small step closer to the vastness of the universe.",
  ui_story_30930601_156_dialog_content = "When you put it that way, it sounds like science is full of nothing but obstacles...",
  ui_story_30930601_157_dialog_content = "But therein lies the joy of research.",
  ui_story_30930601_158_dialog_content = "I have never been afraid of failure. After all, disproving ideas is an integral part of research.",
  ui_story_30930601_159_dialog_content = "All the same, thank you, PlayerName.",
  ui_story_30930601_160_dialog_content = "Your concern is more than enough to give me the strength to keep moving forward.",
  ui_story_30930601_161_dialog_content = "Migard...",
  ui_story_30930601_162_dialog_content = "Even so, I am still a talented biologist.",
  ui_story_30930601_163_dialog_content = "Starting an experimental project with me means higher chances of success than with others.",
  ui_story_30930601_164_dialog_content = "That's why...",
  ui_story_30930601_165_dialog_content = "My next experiment will be to probe the mind and brain structure of the common gamer.",
  ui_story_30930601_166_dialog_content = "And my assistant for this experiment... will be none other than you, PlayerName!",
  ui_story_30930601_167_option_content = "Nope.",
  ui_story_30930601_168_option_content = "Not a chance.",
  ui_story_30930601_169_option_content = "Absolutely not.",
  ui_story_30930601_170_dialog_content = "Turning me down so quickly, hmm...?",
  ui_story_30930601_171_dialog_content = "(Why does it feel like she isn't going to take no for an answer...?)",
  ui_story_30930601_172_dialog_content = "(And that look in her eyes... It's even creepier than usual!!)",
  ui_story_30930601_173_dialog_content = "If I can't have Gronru as a test subject, the next best thing would be someone who has been profoundly influenced by her. Someone like you, PlayerName...",
  ui_story_30930601_174_dialog_content = "Ah, what a wonderful stroke of luck that my experiment materials arrived at my door so early this morning!",
  ui_story_30930601_175_dialog_content = "Now to gently, and carefully... open up PlayerName's head and see what's inside.",
  ui_story_30930601_176_dialog_content = "I said I want no part in this!",
  ui_story_30930601_177_dialog_content = "We'll find success together, no matter how many failures it takes!",
  ui_story_30930601_178_dialog_content = "Come! Let's delve into the mysteries of science together!",
  ui_story_30930601_179_dialog_content = "G-Get away from me! Heeeelp!!!"
}
return config
